def transform_ignore(ctx: click.Context, param: click.Parameter, value:
    Tuple[str]) ->Dict[str, Dict[str, Optional[str]]]:
    ignore_vulns = {}
    if value:
        for item in value:
            # Handle comma-separated values within each item
            ids = [v.strip() for v in item.split(',') if v.strip()]
            for vuln_id in ids:
                ignore_vulns[vuln_id] = {'expires': None, 'reason': ''}
    return ignore_vulns
